{
  "$schema": "https://kurone-kito.github.io/idd-skill/schemas/policy.schema.json",
  "iddVersion": "0.14.0",
  "markerPrefix": "idd-skill",
  "mergePolicy": "fully_autonomous_merge",
  "mergePolicyAck": "fully_autonomous_merge",
  "reviewPolicy": "copilot-advisory",
  "threadResolutionPolicy": "fast-agent-resolve",
  "claimTiming": {
    "staleAge": "PT24H",
    "heartbeatInterval": "PT12H"
  },
  "trustedMarkerActors": [
    "kurone-kito"
  ],
  "advisoryBotLogins": [
    "coderabbitai[bot]",
    "chatgpt-codex-connector[bot]"
  ],
  "workshop": {
    "exampleRepository": "kurone-kito/vrc-event-calendar"
  },
  "commands": {
    "install-deps": "node scripts/verify-install-deps.mjs --key-binary node_modules/.bin/tsc --install-command \"pnpm install --frozen-lockfile\"",
    "fix-validate": "npx biome check --write --error-on-warnings && npx dprint fmt \"**/*.md\" && npx markdownlint-cli2 --fix \"**/*.md\" && npx markdownlint-cli2 \"**/*.md\"",
    "pre-push-validate": "npx biome check --error-on-warnings && npx dprint check \"**/*.md\" && npx markdownlint-cli2 \"**/*.md\" && npx cspell lint \"**\" --no-progress && node scripts/audit-docs.mjs --check && node scripts/audit-code-span-wrap.mjs && pnpm run test:scripts && pnpm run build:check && pnpm run typecheck && node scripts/idd-doctor.mjs --cleanup-backlog-window-days 1 && node scripts/token-cost-report.mjs --check",
    "post-fix-validate": "npx biome check --write --error-on-warnings && npx dprint fmt \"**/*.md\" && npx markdownlint-cli2 --fix \"**/*.md\" && npx markdownlint-cli2 \"**/*.md\" && npx cspell lint \"**\" --no-progress && node scripts/audit-docs.mjs --check && node scripts/audit-code-span-wrap.mjs && pnpm run typecheck"
  },
  "helperRuntime": {
    "profile": "package-manager"
  },
  "issueScope": "roadmap-first",
  "orphanFirstPolicy": "none",
  "issueAuthoring": {
    "journalIssue": "kurone-kito/idd-skill#2674"
  },
  "advisoryWait": {
    "convergenceScope": "idd-claimed",
    "convergenceDeadline": "PT9H",
    "secondaryBotLogin": "coderabbitai[bot]",
    "secondaryQuietWindow": "PT1H"
  },
  "discover": {
    "selectionDesync": "session-offset"
  },
  "critiqueLoop": {
    "deferAfterRounds": 5,
    "deferByUrgency": "severity-tiered",
    "telemetryHook": {
      "command": "idd-critique-telemetry"
    }
  },
  "forcedHandoff": {
    "mode": "human-gated",
    "authorityPolicy": "owners-and-maintainers-only"
  },
  "autopilotSuitability": {
    "floor": 3
  },
  "worktreeGuard": {
    "enabled": true
  },
  "githubApi": {
    "readCache": {
      "enabled": true
    },
    "loadControl": {
      "enabled": true,
      "maxConcurrent": 4
    }
  },
  "ciGate": {
    "trustEmptyProtectionReads": true,
    "externalChecks": {
      "waivable": [
        { "selector": "idd-advisory-convergence", "matchMode": "exact" }
      ]
    },
    "externalCheckWaivers": {
      "mode": "maintainer-authorized",
      "authorityPolicy": "owners-and-maintainers-only",
      "maxValidity": "PT24H"
    }
  }
}

